import React, { useState, useEffect } from 'react';
import axios from 'axios';
import toast, { Toaster } from 'react-hot-toast';
import { 
  FaUser, FaEnvelope, FaPhone, FaCalendarAlt, FaGraduationCap, 
  FaChurch, FaMapMarkerAlt, FaDollarSign, FaUsers, FaShieldAlt,
  FaEye, FaEyeSlash, FaTrash, FaHeart, FaLightbulb, FaHandsHelping,
  FaCross, FaUniversity, FaMobileAlt, FaMapMarker, FaCheckCircle,
  FaTimesCircle, FaClock, FaArrowRight, FaBuilding, FaBookOpen,
  FaChartLine, FaGlobe, FaPrayingHands
} from 'react-icons/fa';
import { GiWhiteBook, GiHolyGrail } from 'react-icons/gi';

function App() {
  const [formData, setFormData] = useState({
    surname: '', given_name: '', institution: '', dob: '', sex: '', marital_status: '',
    home_province: '', country: 'Papua New Guinea', denomination: '', address: '', 
    phone: '', mobile: '', email: '',
    college_university: '', member_role: '', leader_position: '', year_of_graduation: '', field_of_study: '',
    graduate_program: '', fortnightly_amount: '', monthly_amount: '', yearly_amount: '',
    donation_amount: '', membership_type: '', membership_amount: '', 
    membership_new_renewal: 'New', membership_number: ''
  });

  const [members, setMembers] = useState([]);
  const [showAdmin, setShowAdmin] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeSection, setActiveSection] = useState('personal');

  // Modern Color Palette
  const colors = {
    primary: '#0f2b3d',
    primaryDark: '#0a1f2c',
    secondary: '#2c5f7a',
    accent: '#e8a53e',
    accentLight: '#f5c97b',
    success: '#2ecc71',
    danger: '#e74c3c',
    warning: '#f39c12',
    light: '#f8f9fa',
    dark: '#2c3e50',
    gradientStart: '#0f2b3d',
    gradientEnd: '#1a4a6e',
    cardBg: '#ffffff',
    borderLight: '#e9ecef'
  };

  useEffect(() => {
    fetchMembers();
  }, []);

  const fetchMembers = async () => {
    try {
      const response = await axios.get('/api/members');
      setMembers(response.data);
    } catch (err) {
      toast.error('Failed to fetch members');
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await axios.post('/api/members', formData);
      toast.success('Application submitted successfully!');
      setFormData({
        surname: '', given_name: '', institution: '', dob: '', sex: '', marital_status: '',
        home_province: '', country: 'Papua New Guinea', denomination: '', address: '', 
        phone: '', mobile: '', email: '',
        college_university: '', member_role: '', leader_position: '', year_of_graduation: '', field_of_study: '',
        graduate_program: '', fortnightly_amount: '', monthly_amount: '', yearly_amount: '',
        donation_amount: '', membership_type: '', membership_amount: '', 
        membership_new_renewal: 'New', membership_number: ''
      });
      fetchMembers();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } catch (err) {
      toast.error('Error submitting application. Email may already exist.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const updateStatus = async (id, status) => {
    try {
      await axios.put(`/api/members/${id}/status`, { application_status: status });
      toast.success(`Application ${status}`);
      fetchMembers();
    } catch (err) {
      toast.error('Failed to update status');
    }
  };

  const deleteMember = async (id) => {
    if (window.confirm('Are you sure you want to delete this application?')) {
      try {
        await axios.delete(`/api/members/${id}`);
        toast.success('Application deleted');
        fetchMembers();
      } catch (err) {
        toast.error('Failed to delete');
      }
    }
  };

  const graduatePrograms = [
    'Moore Bible College', 'Queensland Theological Seminary', 'Ministry Apprentice (MA)',
    'SAIACS - India', 'Corporate Training', 'Ministry Training Program', 
    'Seminars', 'Conferences', 'Empowerment Training'
  ];

  const membershipTypes = [
    { type: 'Student Member', amount: 20, icon: FaGraduationCap, description: 'Perfect for current students', color: '#3498db' },
    { type: 'Graduate Member', amount: 200, icon: FaUser, description: 'For working professionals', color: '#9b59b6' },
    { type: 'Life Member', amount: 2500, icon: FaHeart, description: 'Lifetime partnership', color: '#e74c3c' },
    { type: 'Partner', amount: 0, icon: FaHandsHelping, description: 'Support as led', color: '#f39c12' }
  ];

  const getStatusColor = (status) => {
    switch(status) {
      case 'approved': return '#2ecc71';
      case 'rejected': return '#e74c3c';
      default: return '#f39c12';
    }
  };

  const getStatusIcon = (status) => {
    switch(status) {
      case 'approved': return <FaCheckCircle />;
      case 'rejected': return <FaTimesCircle />;
      default: return <FaClock />;
    }
  };

  const scrollToSection = (sectionId) => {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'start' });
      setActiveSection(sectionId);
    }
  };

  return (
    <div style={{ background: 'linear-gradient(135deg, #f5f7fa 0%, #e9edf2 100%)', minHeight: '100vh' }}>
      <Toaster position="top-right" toastOptions={{ duration: 4000 }} />

      {/* Modern Navigation Bar */}
      <nav style={{ background: colors.primary, boxShadow: '0 10px 30px rgba(0,0,0,0.1)', position: 'sticky', top: 0, zIndex: 1000 }}>
        <div className="container mx-auto px-6 py-4">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div style={{ background: colors.accent, width: 45, height: 45, borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <FaCross style={{ color: 'white', fontSize: '24px' }} />
              </div>
              <div>
                <h1 className="text-white font-bold text-lg">TSCF Vision Partners</h1>
                <p className="text-gray-300 text-xs">Membership Management System</p>
              </div>
            </div>
            <div className="flex gap-3">
              <button onClick={() => scrollToSection('personal')} style={{ color: activeSection === 'personal' ? colors.accent : 'white', background: 'transparent', border: 'none', cursor: 'pointer', padding: '8px 16px', borderRadius: '8px', transition: 'all 0.3s' }}>Personal</button>
              <button onClick={() => scrollToSection('education')} style={{ color: activeSection === 'education' ? colors.accent : 'white', background: 'transparent', border: 'none', cursor: 'pointer', padding: '8px 16px', borderRadius: '8px' }}>Education</button>
              <button onClick={() => scrollToSection('programs')} style={{ color: activeSection === 'programs' ? colors.accent : 'white', background: 'transparent', border: 'none', cursor: 'pointer', padding: '8px 16px', borderRadius: '8px' }}>Programs</button>
              <button onClick={() => scrollToSection('membership')} style={{ color: activeSection === 'membership' ? colors.accent : 'white', background: 'transparent', border: 'none', cursor: 'pointer', padding: '8px 16px', borderRadius: '8px' }}>Membership</button>
            </div>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <div style={{ background: `linear-gradient(135deg, ${colors.gradientStart}, ${colors.gradientEnd})`, position: 'relative', overflow: 'hidden' }}>
        <div style={{ position: 'absolute', top: -50, right: -50, width: 200, height: 200, background: `radial-gradient(circle, ${colors.accent}20, transparent)`, borderRadius: '50%' }}></div>
        <div className="container mx-auto px-6 py-12 relative">
          <div className="text-center">
            <div className="inline-flex items-center gap-2 bg-white/10 backdrop-blur rounded-full px-4 py-2 mb-6">
              <GiHolyGrail style={{ color: colors.accent }} />
              <span className="text-white text-sm">The Voice of Truth</span>
            </div>
            <h1 className="text-5xl md:text-7xl font-bold text-white mb-4" style={{ textShadow: '2px 2px 4px rgba(0,0,0,0.2)' }}>SALT & LIGHT</h1>
            <p className="text-xl text-gray-200 mb-8">Raising gatekeepers for national transformation</p>
            <div className="grid md:grid-cols-3 gap-6 max-w-4xl mx-auto mt-12">
              <div style={{ background: 'rgba(255,255,255,0.1)', backdropFilter: 'blur(10px)', borderRadius: '16px', padding: '20px' }}>
                <FaLightbulb style={{ color: colors.accent, fontSize: '32px', marginBottom: '12px' }} />
                <h3 className="text-white font-semibold mb-2">Our Vision</h3>
                <p className="text-gray-200 text-sm">Mobilizing graduates to impact the marketplace and nation towards salvation and transformation</p>
              </div>
              <div style={{ background: 'rgba(255,255,255,0.1)', backdropFilter: 'blur(10px)', borderRadius: '16px', padding: '20px' }}>
                <FaUsers style={{ color: colors.accent, fontSize: '32px', marginBottom: '12px' }} />
                <h3 className="text-white font-semibold mb-2">Our Mission</h3>
                <p className="text-gray-200 text-sm">Promoting kingdom mindset through divine alignment, strategic alliance, partnership and fellowship</p>
              </div>
              <div style={{ background: 'rgba(255,255,255,0.1)', backdropFilter: 'blur(10px)', borderRadius: '16px', padding: '20px' }}>
                <FaShieldAlt style={{ color: colors.accent, fontSize: '32px', marginBottom: '12px' }} />
                <h3 className="text-white font-semibold mb-2">Core Values</h3>
                <p className="text-gray-200 text-sm">Truth, Servant Leadership, Integrity, Teamwork, Empowerment, Partnership, Advocacy</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Main Form Container */}
      <div className="container mx-auto px-6 py-12">
        <div className="text-center mb-10">
          <h2 className="text-4xl font-bold" style={{ color: colors.primary }}>TSCF VISION PARTNERS FORM 2026</h2>
          <div style={{ width: '80px', height: '4px', background: colors.accent, margin: '16px auto', borderRadius: '2px' }}></div>
          <p className="text-gray-600">Join the movement of graduates transforming nations</p>
        </div>

        <form onSubmit={handleSubmit}>
          {/* Section 1: Personal Information */}
          <div id="personal" style={{ background: colors.cardBg, borderRadius: '24px', boxShadow: '0 20px 40px rgba(0,0,0,0.08)', marginBottom: '32px', overflow: 'hidden' }}>
            <div style={{ padding: '24px 32px', background: `linear-gradient(135deg, ${colors.primary}10, transparent)`, borderBottom: `2px solid ${colors.accent}` }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <div style={{ background: colors.accent, width: '48px', height: '48px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <FaUser style={{ color: 'white', fontSize: '24px' }} />
                </div>
                <div>
                  <h3 className="text-2xl font-bold" style={{ color: colors.primary }}>Personal Information</h3>
                  <p className="text-gray-500 text-sm">Tell us about yourself</p>
                </div>
              </div>
            </div>
            <div style={{ padding: '32px' }}>
              <div className="grid md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Surname *</label>
                  <input name="surname" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:border-2 transition-all" style={{ focusBorderColor: colors.accent }} value={formData.surname} onChange={handleChange} required />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Given Name *</label>
                  <input name="given_name" className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:border-2 transition-all" style={{ focusBorderColor: colors.accent }} value={formData.given_name} onChange={handleChange} required />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Institution</label>
                  <input name="institution" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.institution} onChange={handleChange} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2"><FaCalendarAlt className="inline mr-2" />Date of Birth</label>
                  <input type="date" name="dob" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.dob} onChange={handleChange} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Sex (Tick)</label>
                  <div className="flex gap-6">
                    <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="sex" value="Male" checked={formData.sex === 'Male'} onChange={handleChange} style={{ accentColor: colors.accent }} /> Male</label>
                    <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="sex" value="Female" checked={formData.sex === 'Female'} onChange={handleChange} style={{ accentColor: colors.accent }} /> Female</label>
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Marital Status</label>
                  <div className="flex flex-wrap gap-4">
                    <label className="flex items-center gap-2"><input type="radio" name="marital_status" value="Married" checked={formData.marital_status === 'Married'} onChange={handleChange} /> Married</label>
                    <label className="flex items-center gap-2"><input type="radio" name="marital_status" value="Single" checked={formData.marital_status === 'Single'} onChange={handleChange} /> Single</label>
                    <label className="flex items-center gap-2"><input type="radio" name="marital_status" value="Divorced" checked={formData.marital_status === 'Divorced'} onChange={handleChange} /> Divorced</label>
                    <label className="flex items-center gap-2"><input type="radio" name="marital_status" value="Other" checked={formData.marital_status === 'Other'} onChange={handleChange} /> Other</label>
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Home Province</label>
                  <input name="home_province" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.home_province} onChange={handleChange} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Country</label>
                  <input name="country" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.country} onChange={handleChange} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">Denomination</label>
                  <input name="denomination" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.denomination} onChange={handleChange} />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-sm font-semibold text-gray-700 mb-2"><FaMapMarkerAlt className="inline mr-2" />Address</label>
                  <textarea name="address" className="w-full px-4 py-3 border border-gray-200 rounded-xl" rows="2" value={formData.address} onChange={handleChange}></textarea>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2"><FaPhone className="inline mr-2" />Phone</label>
                  <input name="phone" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.phone} onChange={handleChange} />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2"><FaMobileAlt className="inline mr-2" />Mobile</label>
                  <input name="mobile" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.mobile} onChange={handleChange} />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-sm font-semibold text-gray-700 mb-2"><FaEnvelope className="inline mr-2" />Email *</label>
                  <input type="email" name="email" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.email} onChange={handleChange} required />
                </div>
              </div>
            </div>
          </div>

          {/* Section 2: Educational Information */}
          <div id="education" style={{ background: colors.cardBg, borderRadius: '24px', boxShadow: '0 20px 40px rgba(0,0,0,0.08)', marginBottom: '32px', overflow: 'hidden' }}>
            <div style={{ padding: '24px 32px', background: `linear-gradient(135deg, ${colors.primary}10, transparent)`, borderBottom: `2px solid ${colors.accent}` }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <div style={{ background: colors.accent, width: '48px', height: '48px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <FaGraduationCap style={{ color: 'white', fontSize: '24px' }} />
                </div>
                <div>
                  <h3 className="text-2xl font-bold" style={{ color: colors.primary }}>Educational Information</h3>
                  <p className="text-gray-500 text-sm">Your academic background</p>
                </div>
              </div>
            </div>
            <div style={{ padding: '32px' }}>
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2"><FaBuilding className="inline mr-2" />College/University attended</label>
                  <input name="college_university" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.college_university} onChange={handleChange} />
                </div>
                <div className="grid md:grid-cols-3 gap-6">
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-2">As a member</label>
                    <input name="member_role" placeholder="Member / Leader" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.member_role} onChange={handleChange} />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-2">As Leader</label>
                    <input name="leader_position" placeholder="Position held" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.leader_position} onChange={handleChange} />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-2">Year of Graduation</label>
                    <input type="number" name="year_of_graduation" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.year_of_graduation} onChange={handleChange} />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2"><FaBookOpen className="inline mr-2" />Field of Study</label>
                  <input name="field_of_study" className="w-full px-4 py-3 border border-gray-200 rounded-xl" value={formData.field_of_study} onChange={handleChange} />
                </div>
              </div>
            </div>
          </div>

          {/* Section 3: Partners Programs */}
          <div id="programs" style={{ background: colors.cardBg, borderRadius: '24px', boxShadow: '0 20px 40px rgba(0,0,0,0.08)', marginBottom: '32px', overflow: 'hidden' }}>
            <div style={{ padding: '24px 32px', background: `linear-gradient(135deg, ${colors.primary}10, transparent)`, borderBottom: `2px solid ${colors.accent}` }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <div style={{ background: colors.accent, width: '48px', height: '48px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <FaPrayingHands style={{ color: 'white', fontSize: '24px' }} />
                </div>
                <div>
                  <h3 className="text-2xl font-bold" style={{ color: colors.primary }}>Partners Programs</h3>
                  <p className="text-gray-500 text-sm">Select your ministry track</p>
                </div>
              </div>
            </div>
            <div style={{ padding: '32px' }}>
              <div style={{ background: `linear-gradient(135deg, ${colors.accent}10, transparent)`, borderRadius: '16px', padding: '24px', marginBottom: '24px' }}>
                <label className="block text-sm font-semibold text-gray-800 mb-4">Graduate Programs (Select one)</label>
                <div className="grid md:grid-cols-2 gap-3">
                  {graduatePrograms.map(program => (
                    <label key={program} className="flex items-center gap-3 p-3 rounded-xl cursor-pointer transition-all hover:bg-white" style={{ background: formData.graduate_program === program ? `${colors.accent}20` : 'transparent' }}>
                      <input type="radio" name="graduate_program" value={program} checked={formData.graduate_program === program} onChange={handleChange} style={{ accentColor: colors.accent }} />
                      <span>{program}</span>
                    </label>
                  ))}
                </div>
              </div>

              <div style={{ background: '#f8f9fa', borderRadius: '16px', padding: '24px', marginBottom: '24px' }}>
                <label className="block text-sm font-semibold text-gray-800 mb-4"><FaDollarSign className="inline mr-2" style={{ color: colors.accent }} />Financial Partnership (Kina)</label>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div><label className="text-xs text-gray-500">Fortnightly</label><input type="number" step="0.01" name="fortnightly_amount" className="w-full px-3 py-2 border border-gray-200 rounded-lg" placeholder="0.00" value={formData.fortnightly_amount} onChange={handleChange} /></div>
                  <div><label className="text-xs text-gray-500">Monthly</label><input type="number" step="0.01" name="monthly_amount" className="w-full px-3 py-2 border border-gray-200 rounded-lg" placeholder="0.00" value={formData.monthly_amount} onChange={handleChange} /></div>
                  <div><label className="text-xs text-gray-500">Yearly</label><input type="number" step="0.01" name="yearly_amount" className="w-full px-3 py-2 border border-gray-200 rounded-lg" placeholder="0.00" value={formData.yearly_amount} onChange={handleChange} /></div>
                  <div><label className="text-xs text-gray-500">One-time Donation</label><input type="number" step="0.01" name="donation_amount" className="w-full px-3 py-2 border border-gray-200 rounded-lg" placeholder="0.00" value={formData.donation_amount} onChange={handleChange} /></div>
                </div>
              </div>

              <div style={{ background: `linear-gradient(135deg, ${colors.secondary}10, transparent)`, borderRadius: '16px', padding: '24px', borderLeft: `4px solid ${colors.accent}` }}>
                <p className="font-bold" style={{ color: colors.primary }}><FaUniversity className="inline mr-2" />TSCF Banking Details</p>
                <p className="font-mono text-sm mt-2">Tertiary Students Christian Fellowship</p>
                <p className="font-mono text-sm">Account: 1000435676 | Bank South Pacific, Boroko Banking Centre</p>
                <p className="font-mono text-sm">BSB NO: 088-943 | SWIFT CODE: BOSPPGPM</p>
              </div>
            </div>
          </div>

          {/* Section 4: Type of Membership */}
          <div id="membership" style={{ background: colors.cardBg, borderRadius: '24px', boxShadow: '0 20px 40px rgba(0,0,0,0.08)', marginBottom: '32px', overflow: 'hidden' }}>
            <div style={{ padding: '24px 32px', background: `linear-gradient(135deg, ${colors.primary}10, transparent)`, borderBottom: `2px solid ${colors.accent}` }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <div style={{ background: colors.accent, width: '48px', height: '48px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <FaHeart style={{ color: 'white', fontSize: '24px' }} />
                </div>
                <div>
                  <h3 className="text-2xl font-bold" style={{ color: colors.primary }}>Membership Type</h3>
                  <p className="text-gray-500 text-sm">Choose your partnership level</p>
                </div>
              </div>
            </div>
            <div style={{ padding: '32px' }}>
              <div className="flex flex-wrap gap-6 mb-8">
                <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="membership_new_renewal" value="New" checked={formData.membership_new_renewal === 'New'} onChange={handleChange} style={{ accentColor: colors.accept }} /> <span className="font-semibold">New Application</span></label>
                <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="membership_new_renewal" value="Renewal" checked={formData.membership_new_renewal === 'Renewal'} onChange={handleChange} style={{ accentColor: colors.accent }} /> <span className="font-semibold">Renewal</span></label>
                {formData.membership_new_renewal === 'Renewal' && (
                  <input name="membership_number" className="px-3 py-2 border border-gray-200 rounded-lg w-48" placeholder="Membership No." value={formData.membership_number} onChange={handleChange} />
                )}
              </div>
              <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
                {membershipTypes.map((mt, idx) => (
                  <div key={idx} onClick={() => setFormData({ ...formData, membership_type: mt.type })} style={{ cursor: 'pointer', border: formData.membership_type === mt.type ? `2px solid ${colors.accent}` : '2px solid #e9ecef', borderRadius: '16px', padding: '20px', textAlign: 'center', transition: 'all 0.3s', background: formData.membership_type === mt.type ? `${colors.accent}10` : 'white' }}>
                    <mt.icon style={{ color: mt.color, fontSize: '40px', marginBottom: '12px' }} />
                    <h4 className="font-bold" style={{ color: colors.primary }}>{mt.type}</h4>
                    {mt.amount > 0 && <p className="text-2xl font-bold mt-2" style={{ color: colors.accent }}>K{mt.amount}</p>}
                    <p className="text-xs text-gray-500 mt-2">{mt.description}</p>
                    <input type="radio" name="membership_type" value={mt.type} checked={formData.membership_type === mt.type} onChange={handleChange} style={{ marginTop: '12px', accentColor: colors.accent }} />
                  </div>
                ))}
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-2">Custom Amount (Kina)</label>
                <input type="number" step="0.01" name="membership_amount" className="w-64 px-4 py-3 border border-gray-200 rounded-xl" placeholder="Enter custom amount" value={formData.membership_amount} onChange={handleChange} />
              </div>
            </div>
          </div>

          {/* Submit Button */}
          <div className="text-center">
            <button type="submit" disabled={isSubmitting} style={{ background: `linear-gradient(135deg, ${colors.accent}, ${colors.accentLight})`, color: colors.primary, fontWeight: 'bold', padding: '16px 48px', borderRadius: '50px', fontSize: '18px', border: 'none', cursor: 'pointer', transition: 'all 0.3s', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }} onMouseEnter={(e) => e.target.style.transform = 'translateY(-2px)'} onMouseLeave={(e) => e.target.style.transform = 'translateY(0)'}>
              {isSubmitting ? 'Submitting...' : 'Submit Application'} <FaArrowRight className="inline ml-2" />
            </button>
          </div>
        </form>

        {/* Admin Panel */}
        <div className="mt-16 text-center">
          <button onClick={() => setShowAdmin(!showAdmin)} style={{ background: colors.primary, color: 'white', padding: '12px 24px', borderRadius: '50px', border: 'none', cursor: 'pointer' }}>
            {showAdmin ? <><FaEyeSlash className="inline mr-2" />Hide Admin Panel</> : <><FaEye className="inline mr-2" />Show Admin Panel</>}
          </button>
        </div>

        {showAdmin && (
          <div style={{ background: colors.cardBg, borderRadius: '24px', padding: '32px', marginTop: '24px', boxShadow: '0 20px 40px rgba(0,0,0,0.08)' }}>
            <h3 className="text-2xl font-bold mb-6" style={{ color: colors.primary }}>Admin Dashboard</h3>
            <div className="overflow-x-auto">
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ background: colors.primary, color: 'white' }}>
                    <th style={{ padding: '12px', textAlign: 'left' }}>ID</th><th style={{ padding: '12px', textAlign: 'left' }}>Name</th><th style={{ padding: '12px', textAlign: 'left' }}>Email</th><th style={{ padding: '12px', textAlign: 'left' }}>Membership</th><th style={{ padding: '12px', textAlign: 'left' }}>Status</th><th style={{ padding: '12px', textAlign: 'left' }}>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {members.map(member => (
                    <tr key={member.id} style={{ borderBottom: '1px solid #e9ecef' }}>
                      <td style={{ padding: '12px' }}>{member.id}</td>
                      <td style={{ padding: '12px' }}>{member.surname}, {member.given_name}</td>
                      <td style={{ padding: '12px' }}>{member.email}</td>
                      <td style={{ padding: '12px' }}>{member.membership_type || 'N/A'}</td>
                      <td style={{ padding: '12px' }}><span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', background: `${getStatusColor(member.application_status)}20`, color: getStatusColor(member.application_status), padding: '4px 12px', borderRadius: '50px', fontSize: '12px', fontWeight: 'bold' }}>{getStatusIcon(member.application_status)} {member.application_status}</span></td>
                      <td style={{ padding: '12px' }}>
                        <select onChange={(e) => updateStatus(member.id, e.target.value)} value={member.application_status} style={{ padding: '6px 12px', borderRadius: '8px', border: '1px solid #ddd', marginRight: '8px' }}>
                          <option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option>
                        </select>
                        <button onClick={() => deleteMember(member.id)} style={{ color: '#e74c3c', background: 'transparent', border: 'none', cursor: 'pointer' }}><FaTrash /></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      {/* Footer */}
      <footer style={{ background: colors.primaryDark, color: 'white', marginTop: '64px', padding: '48px 0 24px' }}>
        <div className="container mx-auto px-6 text-center">
          <div className="flex justify-center gap-2 items-center mb-4">
            <FaCross style={{ color: colors.accent }} />
            <span className="font-semibold">Tertiary Students Christian Fellowship</span>
          </div>
          <p className="text-sm opacity-80">P. O. Box 6329 Port Boroko, National Capital District</p>
          <p className="text-sm opacity-80 mb-4">Mobile: 73277901</p>
          <p className="text-sm">TSCF Vision Partners Application Form 2026</p>
          <p className="text-xs opacity-60 mt-4">&copy; Tertiary Students Christian Fellowship 2026. All rights reserved.</p>
        </div>
      </footer>
    </div>
  );
}

export default App;
